-- User-provided 2026/27 federation schedule, source-preserving. Original BRSZ/snapshots/events untouched.
create table if not exists public.cc_competition_user_schedule_v1(
 season text not null,
 league_key text not null check(league_key in ('menA','menB','womenI','womenIIA','womenIIB')),
 source_key text not null,
 record_kind text not null check(record_kind in ('fixture','result')),
 home_name text not null,
 away_name text not null,
 match_date date,
 starts_at timestamptz,
 venue text,
 referee text,
 source_status text not null check(source_status in ('scheduled','postponed','played')),
 home_sets integer,
 away_sets integer,
 set_scores jsonb not null default '[]'::jsonb,
 source_note text not null default 'User-provided BRSZ 2026-10-18 (unverified against live federation)',
 imported_at timestamptz not null default now(),
 primary key(season,source_key)
);
alter table public.cc_competition_user_schedule_v1 enable row level security;
revoke all on public.cc_competition_user_schedule_v1 from public,anon,authenticated;
create index if not exists cc_competition_user_schedule_lookup_v1 on public.cc_competition_user_schedule_v1(season,league_key,match_date);

on conflict(season,source_key) do update set league_key=excluded.league_key,record_kind=excluded.record_kind,home_name=excluded.home_name,away_name=excluded.away_name,match_date=excluded.match_date,starts_at=excluded.starts_at,venue=excluded.venue,referee=excluded.referee,source_status=excluded.source_status,home_sets=excluded.home_sets,away_sets=excluded.away_sets,set_scores=excluded.set_scores;
